<template><AppLayout><TablePageLayout><template #filters><div class="space-y-4"><div><h1 class="text-xl font-semibold">{{ t('marketplace.earnings') }}</h1><p class="mt-1 text-sm text-gray-500">{{ t('marketplace.earningsDescription') }}</p></div><div v-if="wallet" class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard :title="t('marketplace.pendingEarnings')" :value="wallet.pending" /><StatCard :title="t('marketplace.withdrawable')" :value="wallet.available" /><StatCard :title="t('marketplace.payoutReserved')" :value="wallet.payout_reserved" /><StatCard :title="t('marketplace.debtBalance')" :value="wallet.debt" /></div><div class="flex flex-wrap items-end gap-3"><label class="text-sm">{{ t('marketplace.fromDate') }}<input v-model="filters.start_date" type="date" class="input mt-1" /></label><label class="text-sm">{{ t('marketplace.toDate') }}<input v-model="filters.end_date" type="date" class="input mt-1" /></label><label class="text-sm">{{ t('marketplace.accountId') }}<input v-model.trim="filters.account_id" inputmode="numeric" class="input mt-1" /></label><label class="text-sm">{{ t('marketplace.model') }}<input v-model.trim="filters.model" data-test="model" class="input mt-1" /></label><button data-test="filter" class="btn btn-primary" @click="load(1)">{{ t('marketplace.applyFilters') }}</button></div><p v-if="error" role="alert" class="text-sm text-red-700">{{ error }} <button class="underline" @click="load(page)">{{ t('marketplace.retry') }}</button></p></div></template>
<template #table><DataTable :columns="columns" :data="items" :loading="loading" row-key="operation_id"><template #empty><p class="p-6 text-sm text-gray-500">{{ t('marketplace.noEarnings') }}</p></template><template #cell-date="{ row }">{{ row.date }}<div class="text-xs text-gray-500">{{ row.operation_id }}</div></template><template #cell-refund_amount="{ row }">{{ row.refund_amount ?? '—' }}</template><template #cell-status="{ row }">{{ ['pending', 'matured', 'reversed'].includes(row.status) ? t(`marketplace.earningStatus_${row.status}`) : row.status }}</template></DataTable></template><template #pagination><Pagination v-if="total > 0" :page="page" :page-size="20" :show-page-size-selector="false" :total="total" @update:page="load" /></template></TablePageLayout></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import TablePageLayout from '@/components/layout/TablePageLayout.vue'
import StatCard from '@/components/common/StatCard.vue'
import DataTable from '@/components/common/DataTable.vue'
import Pagination from '@/components/common/Pagination.vue'
import { getEarnings } from '@/api/supplier'
import type { SupplierEarning, SupplierWallet } from '@/types/marketplace'
const { t } = useI18n(); const filters = reactive({ start_date: '', end_date: '', account_id: '', model: '' }); const items = ref<SupplierEarning[]>([]); const wallet = ref<SupplierWallet | null>(null); const page = ref(1); const total = ref(0); const loading = ref(false); const error = ref('')
const columns = computed(() => [{ key: 'date', label: t('marketplace.date') }, { key: 'account_name', label: t('marketplace.accountName') }, { key: 'model', label: t('marketplace.model') }, { key: 'consumer_charge', label: t('marketplace.consumerCharge') }, { key: 'platform_fee', label: t('marketplace.platformFee') }, { key: 'supplier_net', label: t('marketplace.supplierNet') }, { key: 'refund_amount', label: t('marketplace.refundAmount') }, { key: 'status', label: t('marketplace.status') }])
async function load(next = 1) { loading.value = true; error.value = ''; try { const result = await getEarnings(next, Object.fromEntries(Object.entries(filters).filter(([, value]) => value !== ''))); items.value = result.items; wallet.value = result.wallet; page.value = result.page; total.value = result.total } catch { error.value = t('marketplace.loadFailed') } finally { loading.value = false } }
onMounted(() => load())
</script>
